{
  "subtype": "focus_inference",
  "implied_focus": "The type/category of problem underlying each incident ticket (recurring problem taxonomy)",
  "per_column": [
    {
      "name": "problem_type",
      "supports_focus": true,
      "rationale": "Directly infers and labels the recurring problem category from ticket text, realising the focus of 'types of problems' with a rich, data-inferable taxonomy."
    },
    {
      "name": "is_connectivity_issue",
      "supports_focus": true,
      "rationale": "A meaningful roll-up/grouping facet of problem_type, grouping the dominant connectivity-related categories into a higher-level cut analysts can pivot on."
    },
    {
      "name": "resolution_days",
      "supports_focus": false,
      "rationale": "Entirely NULL across all 500 rows, so it contributes no signal; conceptually it also pertains to resolution effort/duration, not to inferring the type of problem."
    }
  ],
  "focus_coherence": 0.72,
